package com.optilive.tracker
import android.os.Bundle
import android.webkit.WebView
import android.widget.TextView
import androidx.appcompat.app.AppCompatActivity
class WeatherActivity:AppCompatActivity(){
 override fun onCreate(b:Bundle?){super.onCreate(b);setContentView(R.layout.activity_weather);findViewById<TextView>(R.id.back).setOnClickListener{finish()};val w=findViewById<WebView>(R.id.weatherWeb);w.settings.javaScriptEnabled=true;w.settings.domStorageEnabled=true;w.settings.setGeolocationEnabled(true);w.webChromeClient=android.webkit.WebChromeClient();w.loadDataWithBaseURL("https://api.open-meteo.com",html(),"text/html","UTF-8",null)}
 private fun html()="""<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><style>body{margin:0;padding:14px;background:#f4f7fa;font-family:Arial;color:#172433}.card{background:white;border-radius:16px;padding:16px;margin-bottom:12px;box-shadow:0 2px 12px #16334b18}.big{font-size:34px;font-weight:900;color:#087fe3}.dir{font-size:22px;font-weight:800}.muted{color:#748292;font-size:12px}.grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px}.stat{text-align:center;background:#f5f8fb;border-radius:12px;padding:12px 4px}.stat b{display:block;font-size:17px}.hour{display:grid;grid-template-columns:58px 1fr 1fr 1fr;padding:11px 0;border-bottom:1px solid #edf1f4;font-size:13px}.head{font-weight:800;color:#6a7887}.bar{height:8px;background:#dce9f4;border-radius:5px;margin-top:5px}.fill{height:8px;background:#1689e8;border-radius:5px}.warn{color:#d87800;font-weight:800}</style></head><body><div class='card'><div class='muted'>DATOS DEL CAMPO DE REGATAS</div><div id='now' style='margin-top:8px'>Buscando posición de la flota…</div></div><div class='card'><b>Previsión por horas</b><div class='hour head'><span>Hora</span><span>Viento</span><span>Racha</span><span>Dirección</span></div><div id='hours'></div></div><div class='card muted'>Fuente meteorológica: Open-Meteo. Datos de modelo; pueden diferir del viento medido sobre el agua.</div><script>function dirs(d){return['N','NE','E','SE','S','SO','O','NO'][Math.round(d/45)%8]}async function pos(){try{let boats=await(await fetch('https://optilive-node-production.up.railway.app/api/boats')).json();if(boats.length){let p=boats.sort((a,b)=>(b.timestamp||0)-(a.timestamp||0))[0];return{lat:p.lat,lon:p.lon,src:'Flota'}}}catch(e){}return await new Promise((ok,no)=>navigator.geolocation.getCurrentPosition(x=>ok({lat:x.coords.latitude,lon:x.coords.longitude,src:'Este móvil'}),no,{enableHighAccuracy:true,timeout:8000,maximumAge:60000}))}async function go(){try{let p=await pos();let u='https://api.open-meteo.com/v1/forecast?latitude='+p.lat+'&longitude='+p.lon+'&current=temperature_2m,apparent_temperature,precipitation,cloud_cover,wind_speed_10m,wind_direction_10m,wind_gusts_10m&hourly=temperature_2m,precipitation_probability,cloud_cover,wind_speed_10m,wind_direction_10m,wind_gusts_10m&wind_speed_unit=kn&forecast_days=2';let j=await(await fetch(u)).json(),c=j.current;document.getElementById('now').innerHTML='<div class="muted">'+p.src+'</div><div class="big">'+c.wind_speed_10m.toFixed(1)+' kn</div><div class="dir">→ '+dirs(c.wind_direction_10m)+' · '+Math.round(c.wind_direction_10m)+'°</div><div class="grid" style="margin-top:14px"><div class="stat"><b>'+c.wind_gusts_10m.toFixed(1)+' kn</b>Racha</div><div class="stat"><b>'+dirs(c.wind_direction_10m)+'</b>Dirección</div><div class="stat"><b>10 m</b>Altura modelo</div></div>';let start=j.hourly.time.findIndex(x=>x>=c.time),h='';for(let i=Math.max(0,start);i<Math.min(start+12,j.hourly.time.length);i++){h+='<div class="hour"><span>'+j.hourly.time[i].slice(11,16)+'</span><span><b>'+j.hourly.wind_speed_10m[i].toFixed(1)+'</b> kn</span><span class="'+(j.hourly.wind_gusts_10m[i]>20?'warn':'')+'">'+j.hourly.wind_gusts_10m[i].toFixed(1)+' kn</span><span>'+dirs(j.hourly.wind_direction_10m[i])+' '+Math.round(j.hourly.wind_direction_10m[i])+'°</span></div>'}document.getElementById('hours').innerHTML=h}catch(e){document.getElementById('now').innerHTML='<b>Sin datos GPS de la flota.</b><br><span class="muted">Inicia el seguimiento para obtener el parte de esa zona.</span>'}}go();setInterval(go,300000)</script></body></html>"""
}